def features(x, kind):
    from itertools import combinations_with_replacement
    terms = [np.ones(len(x)), *x.T]
    if kind in ('quad', 'cubic'):
        terms += [x[:, inds].prod(1) for inds in combinations_with_replacement(range(4), 2)]
    if kind in ('pure3', 'pure5'):
        terms += [*(x ** 3).T]
    if kind == 'pure5':
        terms += [*(x ** 5).T]
    if kind == 'cubic':
        terms += [x[:, inds].prod(1) for inds in combinations_with_replacement(range(4), 3)]
    if kind == 'tanh':
        terms += [*np.tanh(x).T]
    if kind == 'rat':
        terms += [*(x / (1 + x * x)).T]
    return np.column_stack(terms)
